#include "common.hpp"
#include <filesystem>
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("prepare fasta k output_dir");std::string input=argv[1],out=argv[3];int k=std::stoi(argv[2]);if(k<1||k>32)throw std::runtime_error("bad k");std::filesystem::create_directories(out);auto records=readfa(input);U bases=0;for(auto&r:records)bases+=r.seq.size();std::vector<U>all;all.reserve(bases);for(auto&r:records)foreach_kmer(r.seq,k,[&](U x){all.push_back(x);});std::cerr<<"sort n="<<all.size()<<" k="<<k<<'\n';std::sort(all.begin(),all.end());U n=all.size(),distinct=0,repeated=0,maxfreq=0;for(size_t i=0;i<all.size();){size_t j=i+1;while(j<all.size()&&all[j]==all[i])++j;++distinct;repeated+=(j-i>1);maxfreq=std::max<U>(maxfreq,j-i);i=j;}
std::unordered_map<U,uint32_t> freq;freq.max_load_factor(0.8);freq.reserve(repeated);for(size_t i=0;i<all.size();){size_t j=i+1;while(j<all.size()&&all[j]==all[i])++j;if(j-i>1){if(j-i>UINT32_MAX)throw std::runtime_error("count overflow");freq.emplace(all[i],uint32_t(j-i));}i=j;}all.clear();all.shrink_to_fit();
std::ofstream meta(out+"/counts.csv");meta<<"record,k,n_eligible,n_blocks,n_frequency_gt1,n_frequency_gt10,n_frequency_gt50,n_frequency_gt100,n_lowentropy,n_homopolymer,n_allA,sum_frequency,max_frequency\n";
U total=0;for(auto&r:records){encode(r,k);r.freq.reserve(r.x.size());U gt[4]={},low=0,hom=0,aa=0,sum=0,mx=0;for(size_t i=0;i<r.x.size();++i){auto it=freq.find(r.x[i]);uint32_t f=it==freq.end()?1:it->second;r.freq.push_back(f);gt[0]+=f>1;gt[1]+=f>10;gt[2]+=f>50;gt[3]+=f>100;sum+=f;mx=std::max<U>(mx,f);low+=r.flags[i]&1;hom+=(r.flags[i]>>1)&1;aa+=(r.flags[i]>>2)&1;}save_record(r,out+"/"+r.id+".bin");meta<<r.id<<','<<k<<','<<r.x.size()<<','<<r.blocks.size()<<','<<gt[0]<<','<<gt[1]<<','<<gt[2]<<','<<gt[3]<<','<<low<<','<<hom<<','<<aa<<','<<sum<<','<<mx<<'\n';std::cerr<<"saved "<<r.id<<" n="<<r.x.size()<<" blocks="<<r.blocks.size()<<'\n';total+=r.x.size();std::vector<U>().swap(r.x);std::vector<uint32_t>().swap(r.freq);std::vector<uint8_t>().swap(r.flags);std::string().swap(r.seq);}
if(total!=n){throw std::runtime_error("encoder count mismatch");}
std::ofstream summary(out+"/global.txt");summary<<"eligible="<<n<<"\ndistinct="<<distinct<<"\ndistinct_repeated="<<repeated<<"\nmax_frequency="<<maxfreq<<"\n";std::cerr<<"PASS count universe n="<<n<<" distinct="<<distinct<<" repeated="<<repeated<<'\n';return 0;}catch(const std::exception&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
